function uxGroup10(v){return UX_GROUPS10.find(g=>g.pages.includes(v));}
function uxNormalize10(text){return String(text).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();}
function uxResults10(query){const tokens=uxNormalize10(query).trim().split(/\s+/).filter(Boolean),catalog=[...UX_GROUPS10.flatMap(g=>g.pages.map(view=>({view,part:null,name:UX_LABELS10[view],words:g.name+' '+(TITLES[view]||'')}))),...UX_SEARCH_EXTRA10];return catalog.filter(x=>tokens.every(t=>uxNormalize10(x.name+' '+x.words).includes(t))).sort((a,b)=>tokens.length?Number(Boolean(b.part))-Number(Boolean(a.part)):0);}
