function uxPanelKey10(node,v){const text=node.querySelector('h2,h3')?.textContent||'',cl=node.classList;if(cl.contains('tutorial')||cl.contains('warning')||cl.contains('ux-subnav10'))return null;if(v==='bakery'){if(text.includes('flotila'))return 'fleet';if(text.includes('velkoobchod'))return 'wholesale';if(text.includes('receptury')||text.includes('značka'))return 'products';if(text.includes('výroba')||text.includes('plán'))return 'production';if(node.tagName==='SECTION')return 'sales';return null;}if(v==='finance'){if(text.includes('Čtvrtletní'))return 'plan';if(text.includes('Závazky')||text.includes('splatnost')||text.includes('kontrakty')||text.includes('Obchod a závazky'))return 'dues';if(text.includes('Disponibilní')||node.querySelector('[data-academy-open6]'))return 'cash';return 'result';}if(v==='logistics'){return text.includes('flotila')?'fleet':'coffee';}if(v==='hq'){if(text.includes('Pronajaté')||cl.contains('view-toolbar'))return 'premises';if(text.includes('Digitální'))return 'digital';if(text.includes('oddělení')||text.includes('Oddělení'))return 'departments';if(cl.contains('cards'))return node.previousElementSibling?.querySelector('h2')?.textContent.includes('Digitální')?'digital':node.previousElementSibling?.querySelector('h2')?.textContent.includes('Oddělení')?'departments':'premises';return null;}return null;}
function uxSections10(){if(view==='finance'){const card=[...el('content').children].find(n=>n.querySelector('h2')?.textContent==='Velkoobchodní kontrakty');if(card){const h=state.history.at(-1);card.innerHTML='<h2>Obchod a závazky</h2>'+rows([['Kávový velkoobchod · poslední týden',h?money(h.wholesale):'—'],['Pekárenský velkoobchod · poslední týden',h?money(h.detail.foodWholesale||0):'—']])+'<p class="sub">Smlouvy, odběratele a reklamace spravuj v jejich společném přehledu.</p><div class="actions"><button class="soft" data-ux-link10="business">Kávoví odběratelé</button><button class="soft" data-ux-link10="bakery">Pekárenské smlouvy</button></div>';card.querySelectorAll('[data-ux-link10]').forEach(b=>b.onclick=()=>uxGo10(b.dataset.uxLink10,b.dataset.uxLink10==='bakery'?'wholesale':null));}}const names=UX_PANEL_NAMES10[view];if(!names)return;const content=el('content'),nodes=[...content.children],panels={},assignments=nodes.map(n=>({node:n,key:uxPanelKey10(n,view)}));for(const {node:n,key} of assignments){if(!key)continue;if(!panels[key]){const panel=document.createElement('div');panel.id='ux-panel-'+view+'-'+key;panel.className='ux-panel10';panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby','ux-tab-'+view+'-'+key);n.before(panel);panels[key]=panel;}panels[key].append(n);}const keys=Object.keys(names).filter(k=>panels[k]);if(keys.length<2){for(const p of Object.values(panels)){p.removeAttribute('role');p.removeAttribute('aria-labelledby');}return;}const tabs=document.createElement('div');tabs.className='ux-tabs10';tabs.setAttribute('role','tablist');tabs.setAttribute('aria-label','Podstránky · '+UX_LABELS10[view]);tabs.innerHTML=keys.map(k=>`<button role="tab" id="ux-tab-${view}-${k}" data-ux-part10="${k}" aria-controls="${panels[k].id}">${esc(names[k])}</button>`).join('');content.querySelector('.ux-subnav10').after(tabs);const select=(key,focus=false)=>{uxPanels10[view]=key;for(const k of keys){panels[k].hidden=k!==key;const b=tabs.querySelector('[data-ux-part10="'+k+'"]');b.setAttribute('aria-selected',String(k===key));b.tabIndex=k===key?0:-1;if(focus&&k===key)b.focus();}el('uxPath10').setAttribute('aria-label',UX_LABELS10[view]+' · '+names[key]);};tabs.querySelectorAll('button').forEach((b,i)=>{b.onclick=()=>select(b.dataset.uxPart10);b.onkeydown=e=>{const key=e.key;if(!['ArrowLeft','ArrowRight','Home','End'].includes(key))return;e.preventDefault();const j=key==='Home'?0:key==='End'?keys.length-1:(i+(key==='ArrowRight'?1:-1)+keys.length)%keys.length;select(keys[j],true);};});select(keys.includes(uxPanels10[view])?uxPanels10[view]:keys[0]);}
function uxFounder10(){if(state.stores.length||view!=='city')return;const projects=state.opening6?.projects.filter(p=>!['completed','cancelled'].includes(p.status))||[],suppliers=state.bootstrap6.suppliers.filter(s=>s.enabled),card=document.createElement('section');card.className='ux-founder10';card.id='uxFounder10';card.innerHTML=`<span class="eyelabel">TVOJE PRVNÍ KAVÁRNA</span><h2>${projects.length?'Podnik se připravuje':'Začni adresou a vlastním návrhem'}</h2><p>${projects.length?'Sleduj fáze přípravy, skutečné náklady a dodávky. Bez placené kávy a připraveného týmu se provoz zpozdí.':'Máš '+money(state.cash)+' a prázdnou firmu. Vyber adresu na mapě, vybavení a velikost směn. Potom sjednej dodavatele kávy.'}</p><div class="ux-start-steps10"><span class="${projects.length?'done':''}">1 · Adresa a příprava ${projects.length?'✓':''}</span><span class="${suppliers.length?'done':''}">2 · Dodavatel kávy ${suppliers.length?'✓':''}</span><span>3 · Nábor a otevření</span></div><div class="actions"><button class="soft" id="uxFounderSupply10">${suppliers.length?'Prověřit dodávky':'Sjednat dodavatele kávy'}</button><button class="quiet" id="uxFounderHelp10">Jak vybudovat první provoz</button></div>`;const anchor=el('content').querySelector('.ux-subnav10');anchor.after(card);el('uxFounderSupply10').onclick=()=>goto('supply');el('uxFounderHelp10').onclick=help;}
render=function(...a){UX_BASE10.render(...a);document.body.classList.add('ux-shell10');uxNavigation10();uxSections10();uxFounder10();for(const table of el('content').querySelectorAll('table'))if(!table.closest('.table-scroll,.district-table6')){const wrap=document.createElement('div');wrap.className='table-scroll';table.before(wrap);wrap.append(table);}for(const e of el('content').querySelectorAll('.section-tabs')){e.classList.add('ux-existing-tabs10');e.setAttribute('aria-label',e.getAttribute('aria-label')||'Možnosti stránky');}let tools=el('uxTools10');if(!tools){tools=document.createElement('details');tools.id='uxTools10';tools.className='ux-tools10';tools.innerHTML='<summary>Reporty a údržba</summary><div class="ux-tools-body10"></div>';el('next').before(tools);}for(const id of ['serviceAll6','openPerformance5','weeklyDigest6'])if(el(id))tools.querySelector('div').append(el(id));};
